 onOpen(){const c=this.contentEl;c.createEl('h2',{text:'Purchased seats: '+this.plugin.licenseField(this.license)});new Setting(c).setName('Number of seats purchased').addText(t=>t.setValue(this.count).onChange(v=>this.count=v));new Setting(c).addButton(b=>b.setButtonText('Save').setCta().onClick(async()=>{const n=Number(this.count);if(!Number.isInteger(n)||n<0){new Notice('Enter a nonnegative whole number');return}try{await this.app.fileManager.processFrontMatter(this.license.file,fm=>{fm.License_Seats=n});this.close();this.plugin.refresh();new Notice('Seat count saved')}catch(e){new Notice(e.message)}}))}
